def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    row_cuts = [r for r, row in enumerate(grid)
                if row[0] != bg and all(v == row[0] for v in row)]
    col_cuts = [c for c in range(w)
                if grid[0][c] != bg and all(grid[r][c] == grid[0][c] for r in range(h))]

    def intervals(n, cuts):
        result, start = [], 0
        for cut in cuts:
            if start < cut:
                result.append((start, cut))
            start = cut + 1
        if start < n:
            result.append((start, n))
        return result

    rows = intervals(h, row_cuts)
    cols = intervals(w, col_cuts)
    tiles = [(r0, r1, c0, c1) for r0, r1 in rows for c0, c1 in cols]

    source = max(tiles, key=lambda t: sum(
        grid[r][c] != bg
        for r in range(t[0], t[1])
        for c in range(t[2], t[3])
    ))
    r0, r1, c0, c1 = source
    pattern = [row[c0:c1] for row in grid[r0:r1]]

    out = [row[:] for row in grid]
    for a, b, x, y in tiles:
        if b - a == len(pattern) and y - x == len(pattern[0]):
            for i in range(b - a):
                out[a + i][x:y] = pattern[i][:]
    return out
